import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.CCCdsIgc.js";const p=JSON.parse('{"title":"安全中心","description":"","frontmatter":{},"headers":[],"relativePath":"admin/security-center.md","filePath":"admin/security-center.md"}'),h={name:"admin/security-center.md"};function o(i,t,n,l,s,c){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="安全中心" tabindex="-1">安全中心 <a class="header-anchor" href="#安全中心" aria-label="Permalink to &quot;安全中心&quot;">​</a></h1><p>管理后台「<strong>安全中心</strong>」里的每一项都可以设默认值，并<strong>锁定</strong>（锁定后员工改不了）。保存后几秒内下发到所有员工电脑生效，不用重装。</p><p>大多数项默认就是推荐值。下面按用途列出，「默认」是全新部署时的值。</p><h2 id="文件与操作" tabindex="-1">文件与操作 <a class="header-anchor" href="#文件与操作" aria-label="Permalink to &quot;文件与操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td>工作区隔离</td><td>开</td><td>关掉后 AI 可以改工作区外的文件（危险命令仍然拦截）</td></tr><tr><td>删除保护（回收站）</td><td>开</td><td>删除进回收站，而不是永久删除</td></tr><tr><td>修改文件前自动备份</td><td>开</td><td>覆盖写之前留一份原文件，支持一键还原</td></tr><tr><td>备份容量上限</td><td>512 MB</td><td></td></tr><tr><td>批量删除确认阈值</td><td>20</td><td>一次删超过这个数量要额外确认</td></tr><tr><td>网络访问白名单</td><td>开</td><td>命令只能访问允许的地址</td></tr><tr><td>系统级工具</td><td>关</td><td>注册表、服务、计划任务、WMI</td></tr></tbody></table><h2 id="任务质量" tabindex="-1">任务质量 <a class="header-anchor" href="#任务质量" aria-label="Permalink to &quot;任务质量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td>规划提醒</td><td>开</td><td>做了几步还没列计划时提醒 AI</td></tr><tr><td>检查产出文件</td><td>开</td><td>检查生成的文件能不能打开、是不是空的</td></tr><tr><td>长任务模式</td><td>开</td><td>员工可以打开「长任务」</td></tr><tr><td>单次任务 token 上限</td><td>200 万</td><td>防止一个任务把额度烧光</td></tr><tr><td>AI 用选项向员工提问</td><td>开</td><td>缺信息时弹选项卡片</td></tr></tbody></table><h2 id="能力开关-默认都关-按需给部分同事打开" tabindex="-1">能力开关（默认都关，按需给部分同事打开） <a class="header-anchor" href="#能力开关-默认都关-按需给部分同事打开" aria-label="Permalink to &quot;能力开关（默认都关，按需给部分同事打开）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>浏览器操作</td><td>AI 操作浏览器访问网页</td></tr><tr><td>后台命令</td><td>在后台跑开发服务器之类的长命令</td></tr><tr><td>开发者工具</td><td>grep、批量修改、git、建 PR，见 <a href="/help/guide/developer.html">开发者工具</a></td></tr><tr><td>子代理</td><td>AI 开分身并行调研</td></tr><tr><td>允许主助手派遣专家</td><td>见 <a href="/help/guide/experts.html">专家</a></td></tr><tr><td>命令行 / IDE 接入</td><td><code>flyknit -p</code> 和 IDE 插件，见 <a href="/help/guide/cli-and-ide.html">命令行与 IDE</a></td></tr><tr><td>沙箱任务</td><td>本机 Docker 容器里无人值守写代码，见 <a href="/help/guide/sandbox.html">沙箱任务</a>；另有能否上网、能否改 CI 配置、CPU、内存四项</td></tr></tbody></table><h2 id="记忆与个性化" tabindex="-1">记忆与个性化 <a class="header-anchor" href="#记忆与个性化" aria-label="Permalink to &quot;记忆与个性化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td>学习偏好 / 常用信息 / 经验教训 / 历史任务 / 自动沉淀技能</td><td>开</td><td>可以分别关掉</td></tr><tr><td>允许玩笑类语气、自定义语气和名字</td><td>开</td><td></td></tr><tr><td>允许锁屏运行、保持屏幕常亮</td><td>开</td><td></td></tr><tr><td>允许截图提问</td><td>开</td><td></td></tr><tr><td>员工可以查看上下文用量的详细拆分</td><td>开</td><td></td></tr><tr><td>任务完成通知、通知提示音</td><td>开 / 关</td><td>员工可以自己改</td></tr></tbody></table><h2 id="命令拦截策略" tabindex="-1">命令拦截策略 <a class="header-anchor" href="#命令拦截策略" aria-label="Permalink to &quot;命令拦截策略&quot;">​</a></h2><p>默认已经拦截格式化磁盘、<code>diskpart</code>、改系统目录、关防火墙、关杀毒等危险命令，一般不用改。需要加自己的规则时，在管理后台的策略页添加正则，保存时会校验。</p><p>另外，后台「<strong>工具规则</strong>」可以按工具名和参数配置：直接拦截、每次都要确认、在结果后附提醒、把结果里的敏感内容打码。工具规则只会更严，不会放宽已有的安全检查。</p>',14)])])}const u=d(h,[["render",o]]);export{p as __pageData,u as default};
